import base64, codecs
text = open('png_text.txt','rb').read().decode()
step1 = base64.b64decode(text)  # undo base64
# try XOR keys
best=[]
for k in range(256):
    xored = bytes(b ^ k for b in step1)
    try:
        s = xored.decode('ascii')
    except:
        continue
    rot = codecs.decode(s, 'rot13')
    if all(32 <= ord(c) < 127 for c in rot):
        best.append((k, s, rot))
for k, s, rot in best:
    print('KEY', k)
    print('XORED:', s[:120])
    print('ROT  :', rot[:120])
EOF"}

